#pragma once

// The ways the shell dresses a stock control from the theme: a label, a
// text field, and an OrcaSlicer Button. Widgets the shell paints itself
// (HeaderButton, the swatch cells) read ShellTheme directly; these recipes
// exist so a wxStaticText or a Button never carries a hand-typed font, radius
// or colour of its own.

#include "ShellTheme.hpp"

class Button;
class wxColour;
class wxStaticText;
class wxTextCtrl;

namespace Slic3r::GUI::JusPrin {

// Font from the role, foreground as given: the caller names the colour because
// the same role reads in text_primary, text_secondary or a status colour.
void style_label(wxStaticText& label, const ShellTheme& theme, TextRole role, const wxColour& foreground);

// Body font on the canvas surface in the primary text colour.
void style_text_field(wxTextCtrl& field, const ShellTheme& theme, const ShellPalette& palette);

// Size, padding, radius and font from one of the component.button recipes;
// colours from the palette's secondary action. This is the fork's counterpart
// to Button::SetStyle(ButtonStyle::Regular, type), built from tokens instead
// of the teal tables.
void style_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe);

// The same geometry recipe with the semantic primary action state table.
void style_primary_button(Button& button, const ShellTheme& theme, const ShellPalette& palette,
                          const ButtonRecipe& recipe);

// The same geometry recipe as a link (component.button.link): the primary
// action colour on no fill or border, underlined under the pointer, with the
// focus ring as its only edge.
void style_link_button(Button& button, const ShellTheme& theme, const ShellPalette& palette, const ButtonRecipe& recipe);

} // namespace Slic3r::GUI::JusPrin
#pragma once

#include <wx/colour.h>
#include <wx/font.h>

#include <array>
#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin {

// Semantic colors for one appearance mode, resolved from
// resources/jusprin/ui/design-tokens.json. That file is the authoritative
// source; this struct only carries the values the shell consumes.
struct ShellPalette
{
    wxColour surface_canvas;
    wxColour surface_subtle;
    wxColour surface_raised;
    // A row under the pointer or the keyboard inside a menu or popover.
    wxColour surface_raised_hover;
    wxColour surface_selected;
    wxColour text_primary;
    wxColour text_secondary;
    wxColour border_subtle;
    wxColour border_strong;
    wxColour border_focus;
    wxColour action_primary;
    wxColour action_primary_hover;
    wxColour action_primary_pressed;
    wxColour action_primary_text;
    wxColour action_disabled;
    wxColour action_disabled_text;
    wxColour status_warning;
    wxColour status_success;
    wxColour status_success_on_action;
    wxColour status_danger;
    wxColour overlay_scrim;
    // elevation.subtle's and elevation.medium's shadow colours, with this
    // mode's opacity as alpha.
    wxColour elevation_subtle;
    wxColour elevation_medium;
    // The 3D axis colours, the same in both modes because they name the same
    // handles: a red X, a green Y and a blue Z.
    wxColour axis_x;
    wxColour axis_y;
    wxColour axis_z;
};

// The text roles the token file defines under typography.roles.
enum class TextRole { PageTitle, Section, Body, BodyBold, BodySmall, BodySmallBold, Label, LabelBold, Metadata, MetadataBold };
constexpr size_t kTextRoleCount = 10;

// The numbers behind one text role. Sizes are DIP; weight is 400 or 700.
struct TypeStyle
{
    int size{0};
    int line_height{0};
    int weight{0};
};

// One entry of component.button. Each recipe names only some of these
// fields; the ones it leaves out stay 0.
struct ButtonRecipe
{
    int min_width{0};
    int width{0};
    int height{0};
    int min_height{0};
    int padding_x{0};
    int padding_y{0};
    int icon_size{0};
    int radius{0};
    std::optional<TextRole> text_role;
};

struct ButtonMetrics
{
    ButtonRecipe compact;
    ButtonRecipe window;
    ButtonRecipe choice;
    ButtonRecipe parameter;
    ButtonRecipe icon;
    // The design system's 26 DIP icon target: the canvas tool strip and the
    // reset button in a form row, which stands at the field's height.
    ButtonRecipe icon_compact;
    ButtonRecipe expanded;
    ButtonRecipe secondary;
