new_ns="""// Closes the splash on the frame's first show. It is pushed in front of the
// frame's own handlers because MainFrame's constructor binds a wxEVT_SHOW
// handler after attach_shell runs, and that handler does not pass the event
// on, so one bound on the frame never hears it. It takes itself out on the
// next turn of the event loop: while it handles an event, the frame's handlers
// still follow it in the chain.
class SplashCloser : public wxEvtHandler
{
public:
    explicit SplashCloser(wxWindow& frame) : m_frame(&frame)
    {
        Bind(wxEVT_SHOW, &SplashCloser::on_show, this);
        // A frame destroyed before it is shown must not keep a handler pushed.
        Bind(wxEVT_DESTROY, &SplashCloser::on_destroy, this);
        frame.PushEventHandler(this);
    }

private:
    void on_show(wxShowEvent& event)
    {
        event.Skip();
        if (!event.IsShown() || m_done)
            return;
        if (splash()) {
            BOOST_LOG_TRIVIAL(info) << "JusPrin splash screen closed";
            splash()->Destroy();
            splash() = nullptr;
        }
        m_done = true;
        wxTheApp->CallAfter([this] { remove(); });
    }

    void on_destroy(wxWindowDestroyEvent& event)
    {
        event.Skip();
        if (event.GetEventObject() == m_frame.get())
            remove();
    }

    void remove()
    {
        if (m_frame)
            m_frame->RemoveEventHandler(this);
        m_frame = nullptr;
        // Not deleted here: remove() may run inside this handler's own
        // dispatch of the frame's destroy event.
        wxTheApp->ScheduleForDestruction(this);
    }

    wxWeakRef<wxWindow> m_frame;
    bool                m_done{false};
};

} // namespace

